import sys,numpy as np,cv2,itertools
sys.path.insert(0,'/opt/tools')
from rcb_brush import Session
s=Session(instance='/app/instance.json',render=False);acts=np.load('/app/output/traj_y24_resid_dyn.npz')['actions'];s.reset()
for a in acts:s.step(a)
s.painter.finish();st=s.strokes(); M=[]
for i,x in enumerate(st):
 mask=np.zeros((1024,1024),bool);r0,c0=x['mask_bbox'];data=np.asarray(x['mask'])>=128;h,w=data.shape;mask[r0:r0+h,c0:c0+w]=data;M.append(mask)
T=cv2.cvtColor(cv2.imread('/app/target.png'),cv2.COLOR_BGR2GRAY)<128
base=np.logical_or.reduce(M[:5]);extra=M[5:]
def stats(m):
 inter=(m&T).sum();return inter/(m|T).sum(),inter/m.sum(),inter/T.sum(),int(m.sum()),int(inter)
print('base',stats(base))
for j,m in enumerate(extra):print('extra',j,stats(base|m),'added hit',int((m&~base&T).sum()),'added extra',int((m&~base&~T).sum()))
best=(0,None,None)
for k in range(6):
 for inds in itertools.combinations(range(5),k):
  mm=base.copy()
  for j in inds:mm|=extra[j]
  v=stats(mm)[0]
  if v>best[0]:best=(v,inds,stats(mm))
print('best subset',best)
for inds in itertools.chain.from_iterable(itertools.combinations(range(5),k) for k in range(6)):
 if len(inds)==4:
  mm=base.copy()
  for j in inds:mm|=extra[j]
  print('subset4',inds,stats(mm)[0:3])
